  <header class="header">
    <div class="header-inner">
      <div class="brand"><img
          src="data:image/png;base64,"
          alt="Logo Imperial Pizza">
        <div>
          <h1>Controle de Comandas</h1>
          <p>Produção, massas, atendimento, despacho e relatórios</p>
        </div>
      </div>
      <div class="header-tools">
        <div class="date-box"><label for="globalDate">Data</label><input id="globalDate" type="date"></div>
        <div id="phasePill" class="phase-pill">Sem operação</div>
        <button id="settingsBtn" class="settings-gear" type="button" title="Configurações de comandas"
          aria-label="Abrir configurações">⚙</button>
      </div>
    </div>
    <nav class="desktop-nav">
      <button class="nav-btn active" data-page="dashboard">Dashboard</button>
      <button class="nav-btn" data-page="team">Equipe</button>
      <button class="nav-btn" data-page="production">Produção</button>
      <button class="nav-btn" data-page="mass">Massas</button>
      <button class="nav-btn" data-page="dispatch">Atendimento / Despacho</button>
      <button class="nav-btn" data-page="reports">Relatórios</button>
    </nav>
  </header>
